create schema private;

grant usage on schema private to authenticated;

create function private.is_resident(p_unit_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (select 1 from public.residents r where r.unit_id = p_unit_id and r.user_id = auth.uid())
$$;

create function private.is_building_staff(p_building_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (select 1 from public.building_staff s where s.building_id = p_building_id and s.user_id = auth.uid())
$$;

create function private.unit_building_id(p_unit_id bigint) returns bigint
language sql stable security definer set search_path = ''
as $$
  select u.building_id from public.units u where u.id = p_unit_id
$$;

alter table public.units enable row level security;
alter table public.residents enable row level security;
alter table public.building_staff enable row level security;
alter table public.requests enable row level security;
alter table public.request_photos enable row level security;

create policy "units_select"
  on public.units
  for select
  to authenticated
  using (private.is_resident(id) or private.is_building_staff(building_id));

create policy "residents_select"
  on public.residents
  for select
  to authenticated
  using (user_id = auth.uid());

create policy "building_staff_select"
  on public.building_staff
  for select
  to authenticated
  using (user_id = auth.uid());

create policy "requests_select"
  on public.requests
  for select
  to authenticated
  using (private.is_resident(unit_id) or private.is_building_staff(private.unit_building_id(unit_id)));

create policy "request_photos_select"
  on public.request_photos
  for select
  to authenticated
  using (private.is_resident(request_id) or private.is_building_staff(private.unit_building_id(request_id)));

create policy "requests_insert"
  on public.requests
  for insert
  to authenticated
  with check (created_by = auth.uid() and private.is_resident(unit_id) and status = 'open');

create policy "request_photos_insert"
  on public.request_photos
  for insert
  to authenticated
  with check (
    (private.is_resident(request_id) or private.is_building_staff(private.unit_building_id(request_id)))
    and exists (
      select 1 from public.requests r
      where r.id = request_photos.request_id
        and (private.is_resident(r.unit_id) or private.is_building_staff(private.unit_building_id(r.unit_id)))
    )
  );

create policy "requests_update_status"
  on public.requests
  for update
  to authenticated
  using (private.is_building_staff(private.unit_building_id(unit_id)))
  with check (private.is_building_staff(private.unit_building_id(unit_id)) and status != 'open');

create function public.prevent_request_non_status_update()
returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;
  if new.id is distinct from old.id
     or new.unit_id is distinct from old.unit_id
     or new.created_by is distinct from old.created_by
     or new.description is distinct from old.description then
    raise exception 'Only status can be updated on requests';
  end if;
  return new;
end
$$;

create trigger requests_prevent_non_status_update
  before update on public.requests
  for each row
  execute function public.prevent_request_non_status_update();

create function public.prevent_request_delete()
returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if auth.role() = 'service_role' then
    return old;
  end if;
  raise exception 'Requests cannot be deleted';
end
$$;

create trigger requests_prevent_delete
  before delete on public.requests
  for each row
  execute function public.prevent_request_delete();

create function public.prevent_unit_modify()
returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;
  raise exception 'Units cannot be modified through the app';
end
$$;

create function public.prevent_resident_modify()
returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;
  raise exception 'Residents cannot be modified through the app';
end
$$;

create function public.prevent_staff_modify()
returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;
  raise exception 'Building staff cannot be modified through the app';
end
$$;

create trigger units_prevent_modify
  before update on public.units
  for each row
  execute function public.prevent_unit_modify();

create trigger residents_prevent_modify
  before update on public.residents
  for each row
  execute function public.prevent_resident_modify();

create trigger building_staff_prevent_modify
  before update on public.building_staff
  for each row
  execute function public.prevent_staff_modify();

revoke all on public.units from anon, authenticated;
