create or replace function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer search path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_auction public.auctions%rowtype;
  v_current_highest numeric;
  v_min_increment numeric;
  v_error text;
begin
  -- R4: Check caller is signed in
  if v_uid is null then
    raise exception 'Place bid: not authenticated';
  end if;

  -- R4: Check auction exists
  select * into v_auction from public.auctions where id = p_auction_id;
  if not found then
    raise exception 'Place bid: auction does not exist';
  end if;

  -- R4: Check auction has not ended
  if v_auction.ends_at <= now() then
    raise exception 'Place bid: auction has ended';
  end if;

  -- R4: Check caller is not the seller
  if v_auction.seller_id = v_uid then
    raise exception 'Place bid: cannot bid on your own auction';
  end if;

  -- R4: Get current highest bid and min increment
  select highest_bid, min_increment into v_current_highest, v_min_increment from public.auctions where id = p_auction_id;

  -- R4: Check amount is valid
  if v_current_highest is null then
    -- No bids yet: must be at or above starting price
    if p_amount < v_auction.starting_price then
      raise exception 'Place bid: amount must be at least the starting price';
    end if;
  else
    -- Bids exist: must be above highest bid + min increment
    if p_amount <= (v_current_highest + v_min_increment) then
      raise exception 'Place bid: amount must be above current highest bid plus minimum increment';
    end if;
  end if;

  -- R3: Record the bid
  insert into public.bids (auction_id, bidder_id, amount, placed_at)
  values (p_auction_id, v_uid, p_amount, now());

  -- R3: Update auction's highest bid
  update public.auctions
  set highest_bid = p_amount,
      highest_bidder = v_uid
  where id = p_auction_id;

  return p_amount;
end;
$$;

revoke all on function public.place_bid(bigint, numeric) from public;
revoke all on function public.place_bid(bigint, numeric) from anon;
grant execute on function public.place_bid(bigint, numeric) to authenticated;
grant execute on function public.place_bid(bigint, numeric) to service_role;

revoke all on table public.auctions from anon;
revoke all on table public.bids from anon;

